60	// WHY ONLY local AND worktree SCOPE: the finding is that a REPOSITORY must not
61	// make git run code. A driver in the user's own ~/.gitconfig is not the
62	// repository's code -- `git lfs install` writes filter.lfs.clean there -- and
63	// blanking it would silently corrupt every diff of an LFS repository, since git
64	// would compare a real worktree file against a stored pointer. Local and
65	// worktree scope are exactly the scopes the repository itself carries.
66	
67	// gitConfigOverride is one key/value pair forced onto a git invocation.
68	type gitConfigOverride struct {
69		Key   string
70		Value string
71	}
72	
73	// gitFilterOverrideKeys are the three keys that name an executable, plus the
74	// flag that decides whether blanking them is fatal.
75	var gitFilterOverrideKeys = []struct{ suffix, value string }{
76		{"clean", ""},
77		{"smudge", ""},
78		{"process", ""},
79		{"required", "false"},
80	}
81	
82	// repoFilterEnumerateTimeout bounds the one `git config` probe per repository.
83	const repoFilterEnumerateTimeout = 5 * time.Second
84	
85	// repoFilterDriverOverrides enumerates the current effective configuration on
86	// every invocation. A stat cache of .git/config misses included files, common
87	// worktree configuration, conditional includes, and environment changes. Git's
88	// --show-origin reports active origins only; it cannot prove a previously
89	// inactive include is still inactive without reevaluating configuration.
90	func repoFilterDriverOverrides(ctx context.Context, repoDir string) ([]gitConfigOverride, error) {
91		if strings.TrimSpace(repoDir) == "" {
92			return nil, nil
93		}
94		return enumerateRepoFilterDrivers(ctx, repoDir)
95	}
96	
97	// enumerateRepoFilterDrivers asks git which filter.* keys the repository itself
98	// sets. It spawns git directly rather than going through the hardened runner:
99	// the runner calls back into this function, and `git config` reads no worktree
100	// content, so no filter can run during the probe.
101	//
102	// Spawning directly means hardenedGitArgs does not run here, so this is the one
103	// git invocation in the binary that has to carry gitHardenConfig itself.
104	// Splicing the shared slice in rather than repeating its flags is what keeps
105	// the probe from drifting behind the chokepoint: core.hooksPath was added to
106	// gitHardenConfig after a `.git/hooks/post-index-change` was found to execute
107	// during indexing, and a hand-copied `-c core.fsmonitor=false` here would have
108	// silently missed it. `git config` does not touch the index and so cannot fire
109	// post-index-change today; the flags are applied because "every git spawn is
110	// hardened" is a cheaper invariant to keep than a per-call-site argument about
111	// which hooks a subcommand can reach.
112	func enumerateRepoFilterDrivers(ctx context.Context, repoDir string) ([]gitConfigOverride, error) {
113		if ctx == nil {
114			ctx = context.Background()
115		}
116		runCtx, cancel := context.WithTimeout(ctx, repoFilterEnumerateTimeout)
117		defer cancel()
118		// -z keeps the output unambiguous for a subsection name containing a
119		// newline; --show-scope tells local/worktree apart from global/system.
120		args := append(slices.Clone(gitHardenConfig),
121			"config", "-z", "--show-scope", "--name-only", "--get-regexp", `^filter\..*\.(clean|smudge|process|required)$`)
122		cmd := exec.CommandContext(runCtx, "git", args...)
123		cmd.Dir = repoDir
124		out, err := cmd.Output()
125		if err != nil {
126			if runCtx.Err() != nil {
127				return nil, fmt.Errorf("enumerate repository filter drivers: %w", runCtx.Err())
128			}
129			// Git reports no matching keys with exit 1 and no output. Any other
130			// failure must block the protected command and must not enter the cache.
131			var exitErr *exec.ExitError
132			if errors.As(err, &exitErr) && exitErr.ExitCode() == 1 && len(out) == 0 && len(exitErr.Stderr) == 0 {
133				return nil, nil
134			}
135			return nil, fmt.Errorf("enumerate repository filter drivers: %w", err)
136		}
137		fields := strings.Split(string(out), "\x00")
138		seen := map[string]bool{}
139		var drivers []string
140		for i := 0; i+1 < len(fields); i += 2 {
141			scope, key := fields[i], fields[i+1]
142			if scope != "local" && scope != "worktree" {
143				continue
144			}
145			driver, ok := filterDriverFromConfigKey(key)
146			if !ok || seen[driver] {
147				continue
148			}
149			seen[driver] = true
150			drivers = append(drivers, driver)
151		}
152		var overrides []gitConfigOverride
153		for _, driver := range drivers {
154			for _, k := range gitFilterOverrideKeys {
155				overrides = append(overrides, gitConfigOverride{Key: "filter." + driver + "." + k.suffix, Value: k.value})
156			}
157		}
158		return overrides, nil
159	}
160	
161	// filterDriverFromConfigKey pulls "na=me" out of "filter.na=me.clean". The
162	// driver name is everything between the first and last dot, so a name
163	// containing dots, equals signs or spaces round-trips intact.
164	func filterDriverFromConfigKey(key string) (string, bool) {
165		rest, ok := strings.CutPrefix(key, "filter.")
